  private trace(signal: Signal): Execution {
    const following: string[] = [];
    function visit(s: Signal, depth: number): void {
      following.push(`${' '.repeat(2 * depth)}${s.name} <- ${s.origin}`);
      for (const ingredient of s.ingredients) visit(ingredient, depth + 1);
    }
    visit(signal, 1);
    return { details: signal.name, following };
